        symbol = "PAIN";
        name = "PAIN Token";
        decimals = 18;
        _totalSupply = 21000000000000000000000000;
        balances[0x6115C493111Eb41DCc50C848C3BFF14782041Fb8] = _totalSupply;
        emit Transfer(address(0),0x6115C493111Eb41DCc50C848C3BFF14782041Fb8, _totalSupply);
    }

